T("Accept only ordinary party invitations from the relationship types you select. Invites remain manual in combat, while grouped, during queue-loss or quest-session confirmations, or when Blizzard asks you to choose a role. The native popup handles the final action.", "Aceite apenas convites comuns para grupo das pessoas selecionadas. Os convites continuam manuais em combate, enquanto você já está em grupo, quando uma fila ou confirmação de sessão de missão poderia ser perdida, ou quando a Blizzard pede que você escolha uma função. A janela nativa executa a ação final.")
