T("Adds automatic collection on top of Blizzard's own Auto Loot setting, which stays unchanged. Locked slots and confirmations stay manual.", "Adiciona a coleta automática à opção Saque Automático da própria Blizzard, que permanece inalterada. Espaços bloqueados e confirmações continuam manuais.")
T("Adds guild rank, the hovered unit's target, item levels, the unit's current mount and item or spell details to Blizzard's main tooltip, and can show player names without titles. Your own item level and the one of the unit open in the Inspect window need no request. Item levels of other hovered players are a separate choice that sends inspect requests: at most one per hover, never while the Inspect window or another inspect is busy. Mounts are read once when a unit tooltip opens, out of combat; a change appears on the next hover. Place the fixed corner in MSUF Edit Mode; the cursor offsets apply to the cursor anchor.", "Adiciona à dica principal da Blizzard o posto na guilda, o alvo da unidade, níveis de item, a montaria atual da unidade e detalhes de itens ou feitiços, e pode mostrar nomes de jogadores sem títulos. Seu próprio nível de item e o da unidade aberta na janela de inspeção não precisam de pedido. Níveis de item de outros jogadores sob o cursor são uma opção separada que envia pedidos de inspeção: no máximo um por passagem do cursor e nunca enquanto a janela de inspeção ou outra inspeção estiver ocupada. Montarias são lidas uma vez quando uma dica de unidade abre, fora de combate; uma mudança aparece na próxima passagem. Posicione o canto fixo no modo de edição do MSUF; os deslocamentos do cursor valem para a âncora no cursor.")
T("Adds the current-season Mythic+ score to the main tooltip of another player when Blizzard provides a public score. Unknown or restricted scores stay hidden.", "Adiciona a pontuação Mythic+ da temporada atual à dica principal de outro jogador quando Blizzard fornece uma pontuação pública. Pontuações desconhecidas ou restritas permanecem ocultas.")
T("Adjust the glass effect while keeping your colors and window coverage.", "Ajuste o efeito de vidro mantendo suas cores e a cobertura das janelas.")
T("Adventure Guide", "Guia de aventura")
T("After a completed Mythic+ run or successful raid encounter, show the public result values in a separate card. Choose which figures appear and how long the card stays open. The last result can be reopened here. Combat delays the card until it is safe to show.", "Após concluir uma corrida de Mítica+ ou vencer um encontro de raide, exibe os resultados públicos em um cartão separado. Escolha quais números aparecem e por quanto tempo o cartão fica aberto. O último resultado pode ser reaberto aqui. O combate adia o cartão até ser seguro exibi-lo.")
