T("Blizzard keeps every original font size and style flag.", "A Blizzard mantém cada tamanho de fonte e atributo de estilo originais.")
T("Blizzard keeps its text sizes and outlines.", "A Blizzard mantém seus tamanhos de texto e contornos.")
T("Blizzard keeps the button artwork, clicks, tooltips, enabled states and notifications. Optional glyph artwork is available in the detail controls. Visual changes apply outside combat only.", "A Blizzard mantém a arte dos botões, os cliques, as dicas, os estados de ativação e as notificações. Glifos opcionais estão disponíveis nos controles detalhados. As mudanças visuais só se aplicam fora de combate.")
T("Blizzard layout captured", "Layout da Blizzard capturado")
T("Blizzard layout imported", "Layout da Blizzard importado")
T("Blizzard original", "Original da Blizzard")
T("Blizzard owns aggro flashes, progressive highlights and soft target icons. Optional colors tint Blizzard's existing threat textures; its health bar threat color stays under the role-color overlay. Soft target icons also need the nameplate icon switch enabled and a matching soft target in game.", "A Blizzard controla os flashes de ameaça, destaques progressivos e ícones de alvo suave. As cores opcionais tingem as texturas de ameaça existentes; a cor de ameaça da barra de vida fica sob a cor de função. Os ícones de alvo suave também exigem ícones de placas de nome ativados e um alvo suave correspondente no jogo.")
T("Blizzard owns the aura icons and updates. Choose Keep Blizzard setting or Customize for each unit type. Buffs, debuffs and control effects can be selected and dragged separately in the preview. Aura size uses Blizzard's own setting.", "A Blizzard controla os ícones de aura e suas atualizações. Escolha Manter configuração da Blizzard ou Personalizar para cada tipo de unidade. Bônus, penalidades e efeitos de controle podem ser selecionados e arrastados separadamente na prévia. O tamanho das auras usa a configuração da própria Blizzard.")
T("Blizzard owns these elements. The rarity icon setting applies to all nameplates; raid target icons are hidden only on enemy plates. Castbar details control Blizzard's own castbar. The preview and live plates use the same switches.", "A Blizzard controla estes elementos. A opção de ícone de raridade vale para todas as placas de identificação; os ícones de alvo de raide são ocultados apenas nas placas inimigas. Os detalhes da barra de lançamento controlam a barra de lançamento da própria Blizzard. A prévia e as placas ao vivo usam as mesmas opções.")
T("Blizzard personal auras", "Auras pessoais da Blizzard")
T("Blizzard plate size (health bar + elements)", "Tamanho da placa da Blizzard (barra de vida + elementos)")
T("Blizzard plate style", "Estilo de placa da Blizzard")
T("Blizzard raid target icon on enemy plates", "Ícone de alvo de raide da Blizzard em placas inimigas")
T("Blizzard setting", "Configuração da Blizzard")
T("Blizzard shield", "Escudo da Blizzard")
T("Blizzard spell icon", "Ícone de feitiço da Blizzard")
T("Blizzard supplies health and aura updates. List edits and preview work during combat; color pickers work after combat.", "A Blizzard atualiza vida e auras. Lista e prévia funcionam em combate; os seletores de cor funcionam após o combate.")
T("Blizzard supplies the castbar texture, colors, progress and interrupts. Customize its text and details here. Select and move each cast element in the preview; positions apply outside combat.", "A Blizzard fornece a textura, as cores, o progresso e as interrupções da barra de lançamento. Personalize o texto e os detalhes aqui. Selecione e mova cada elemento de lançamento na prévia; as posições são aplicadas fora de combate.")
T("Blizzard supplies the icons. The Suite keeps its own button plates, bar frame and spacing. Native clicks, tooltips and notifications stay intact.", "A Blizzard fornece os ícones. A Suite mantém suas próprias placas de botão, a moldura da barra e o espaçamento. Cliques, dicas e notificações originais continuam intactos.")
T("Blizzard supplies the name and health values. Mapko requests full enemy plates and both health values so normal enemies show text too. Width and height change only the enemy health bar in pixels; 0 keeps the selected bar dimensions. Backdrop, border and role fill are separate live skin layers in the preview; right-click a layer for its setting. Role colors use the saved palette; mana is only a caster hint. Open the three-dot menu here or Nameplates in MSUF Colors to change the palette.", "A Blizzard fornece o nome e os valores de vida. Mapko solicita placas inimigas completas e ambos os valores de vida para que inimigos normais também exibam texto. Largura e altura alteram apenas a barra de vida inimiga em pixels; 0 mantém as dimensões escolhidas. Fundo, borda e preenchimento de função são camadas separadas na prévia; clique com o botão direito em uma camada para abrir sua configuração. As cores de função usam a paleta salva; mana é apenas uma indicação de conjurador. Abra o menu de três pontos aqui ou Placas de nome em Cores do MSUF para mudar a paleta.")
T("Blizzard symbols", "Símbolos da Blizzard")
T("Blizzard talent mapping: %d", "Mapeamento de talento da Blizzard: %d")
T("Blizzard window controls", "Controles de janela da Blizzard")
