T("Blizzard's own buttons stay functional. The row is their starting position; drag each icon freely in the preview.", "Os botões da própria Blizzard continuam funcionando. A fileira é a posição inicial deles; arraste cada ícone livremente na prévia.")
T("Blizzard's own cooldown swipe fills the ring: the global cooldown after each ability, and casts or channels while they run. A cast takes the place of the global cooldown until it ends; the bright edge marks how far the cast has come.", "A animação de recarga da própria Blizzard preenche o anel: a recarga global após cada habilidade e lançamentos ou canalizações enquanto duram. Um lançamento toma o lugar da recarga global até terminar; a borda brilhante mostra quanto ele avançou.")
