T("Bounded named-root traversal\nDedicated visual-only Edit Mode coverage\nExplicit secure controls remain untouched\nBlizzard frames keep their parents and scripts; only Suite-made selection indicators move\nNo polling or tickers; OnUpdate runs only while a window corner is dragged", "Percurso limitado de raízes nomeadas\nCobertura dedicada e apenas visual do Modo de Edição\nControles protegidos explícitos permanecem intocados\nOs quadros da Blizzard mantêm seus pais e scripts; só os indicadores de seleção criados pela Suite se movem\nSem polling nem tickers; o OnUpdate só roda enquanto um canto da janela é arrastado")
