T("Bubbles outside instances can take the MSUF look; Blizzard locks the ones inside instances. Each source keeps Blizzard's look or uses the MSUF one: the shared look or its own font, size, colors, spacing and width. A bubble is matched to the line it shows right after that line arrives. Turning bubbles off inside instances uses Blizzard's bubble settings and gives them back when you leave or turn it off.", "Os balões fora de instâncias podem usar o visual do MSUF; a Blizzard bloqueia os de dentro das instâncias. Cada origem mantém o visual da Blizzard ou usa o do MSUF: o visual comum ou sua própria fonte, tamanho, cores, espaçamento e largura. Um balão é associado à linha que exibe logo depois que essa linha chega. Desligar os balões dentro de instâncias usa as configurações de balões da Blizzard e as devolve quando você sai ou desliga a opção.")
