T("Choose a look and when the Suite bar appears. Visibility rules use the Suite layout; Blizzard layout keeps Blizzard's visibility. MSUF Edit Mode reveals the bar for moving.", "Escolha um visual e quando a barra da Suite aparece. As regras de visibilidade usam o layout da Suite; o layout da Blizzard mantém a visibilidade da Blizzard. O Modo de Edição do MSUF revela a barra para movê-la.")
T("Choose a look below; this sample follows your changes.", "Escolha um visual abaixo; este exemplo acompanha suas alterações.")
