T("Choose a random owned Hearthstone variant for the next click", "Escolher uma variante de pedra de regresso possuída aleatoriamente para o próximo clique")
T("Choose a smaller stack size and make sure the item is unlocked, your cursor is empty and you are out of combat.", "Escolha uma pilha menor e confira se o item está desbloqueado, o cursor está vazio e você está fora de combate.")
T("Choose a sound", "Escolha um som")
T("Choose a starting point. Existing bars stay unchanged.", "Escolha um ponto de partida. As barras existentes não mudam.")
T("Choose a style above or change these colors to make a Custom look. Rows update immediately.", "Escolha um estilo acima ou altere essas cores para criar uma aparência personalizada. As linhas são atualizadas imediatamente.")
T("Choose a style, font and coverage in minutes. Every deeper control remains available in Expert mode.", "Escolha estilo, fonte e cobertura em minutos. Todos os controles mais detalhados continuam disponíveis no modo Avançado.")
T("Choose a template", "Escolha um modelo")
T("Choose an MSUF font, outline, shadow and Smooth, Sharp or Slug rendering. Slug has no shadow. Label, value and warning colors are separate.", "Escolha uma fonte do MSUF, contorno, sombra e renderização Suave, Nítida ou Slug. Slug não tem sombra. As cores de rótulo, valor e aviso são separadas.")
T("Choose an MSUF or SharedMedia font and bar texture. Font size, outline, shadow, Smooth/Sharp/Slug rendering, bar height and spacing update the HUD immediately. Slug has no shadow.", "Escolha uma fonte e uma textura de barra do MSUF ou do SharedMedia. Tamanho da fonte, contorno, sombra, renderização Suave/Nítida/Slug, altura da barra e espaçamento atualizam o HUD imediatamente. Slug não tem sombra.")
T("Choose at least one DoT to enable aura colors", "Escolha pelo menos um DoT para ativar as cores das auras")
T("Choose broad UI families. Dedicated secure behavior and semantic artwork remain untouched.", "Escolha grandes famílias da interface. O comportamento protegido dedicado e a arte com significado permanecem intocados.")
T("Choose broker names and discovered currency IDs per place. Select your current-season crest currencies from the native currency list; saved currency selections work after login without visiting an upgrade NPC. Selection order and separator control the crest block. Observed upgrade stages remain available as an alternative after selecting an upgrade item this login. Hearthstone actions require a deliberate click.", "Escolha nomes de broker e IDs de moedas descobertas por posição. Selecione suas moedas de brasões da temporada atual na lista nativa; as seleções salvas funcionam após entrar no jogo sem visitar um PNJ de aprimoramento. A ordem de seleção e o separador controlam o bloco de brasões. As etapas de aprimoramento observadas continuam disponíveis como alternativa após selecionar um item para aprimorar nesta sessão. As ações de Pedra de Regresso exigem um clique intencional.")
T("Choose buffs and consumables to track.", "Escolha os bônus e consumíveis que deseja acompanhar.")
T("Choose clean window controls and a complete Micro Bar style, then tune individual artwork only when needed.", "Escolha controles de janela limpos e um estilo completo de microbarra; ajuste artes individuais só quando necessário.")
T("Choose coverage", "Escolha a cobertura")
T("Choose crest currencies", "Escolher moedas de brasões")
T("Choose currencies", "Escolher moedas")
T("Choose data", "Escolher dados")
T("Choose data for place %d", "Escolha os dados da posição %d")
T("Choose data source", "Escolher fonte de dados")
T("Choose discovered currency", "Escolher uma moeda descoberta")
T("Choose each Blizzard popup separately. The feature hides its window when it appears and leaves the underlying game events intact. Combat lockdown can prevent hiding a protected window.", "Escolha cada pop-up Blizzard separadamente. O recurso oculta sua janela quando ela aparece e deixa intactos os eventos subjacentes do jogo. O bloqueio de combate pode impedir a ocultação de uma janela protegida.")
T("Choose individual recurring UI errors to hide with Blizzard's own message filter.", "Escolha erros de IU recorrentes individuais para ocultar com o próprio filtro de mensagens de Blizzard.")
T("Choose loaded broker", "Escolher um plugin broker carregado")
T("Choose modules", "Escolher módulos")
T("Choose observed seasonal stages", "Escolher estágios sazonais observados")
T("Choose one font for Blizzard UI text. Existing sizes, outlines, shadows and accessibility scaling are preserved.", "Escolha uma fonte para o texto da interface da Blizzard. Tamanhos, contornos, sombras e a escala de acessibilidade existentes são mantidos.")
T("Choose preview DoTs", "Escolher DoTs da prévia")
T("Choose the detailed character view and its extra information. Changing the view reloads the UI.", "Escolha a visão detalhada do personagem e suas informações extras. Mudar a visão recarrega a interface.")
T("Choose the dungeon difficulties where MSUF starts the combat log. Mythic+ begins when the keystone starts.", "Escolha as dificuldades de masmorra em que o MSUF inicia o registro de combate. Em Mítica+, ele começa quando a pedra-chave é ativada.")
T("Choose the map shape, then adjust its border and outer shadow.", "Escolha a forma do mapa e depois ajuste a borda e a sombra externa.")
T("Choose the raid difficulties where MSUF starts the combat log.", "Escolha as dificuldades de raide em que o MSUF inicia o registro de combate.")
T("Choose the shared button colors and frame. Layout, bindings and visibility stay as set. Changing an individual color switches the label to Custom.", "Escolha as cores e a moldura compartilhadas dos botões. Layout, atalhos e visibilidade permanecem como definidos. Alterar uma cor individual muda o rótulo para Personalizado.")
T("Choose the values shown on each bar.", "Escolha os valores exibidos em cada barra.")
T("Choose what the Suite tracker lists and when it steps aside.", "Escolha o que o rastreador Suite lista e quando ele sai do caminho.")
T("Choose where recent actions appear. Delves have their own switch; battlegrounds and arenas share one, and other scenarios follow Outside instances. Where the tracker is switched off, it does not listen to your casts.", "Escolha onde as ações recentes aparecem. As imersões têm um interruptor próprio; campos de batalha e arenas compartilham um, e os demais cenários seguem \"Fora de instâncias\". Onde o registro está desligado, ele não escuta seus lançamentos.")
T("Choose which Blizzard interfaces receive the skin. Blizzard keeps their interactions.", "Escolha quais interfaces da Blizzard recebem a skin. A Blizzard mantém as interações delas.")
T("Choosing a look updates Skinning and every enabled Suite module. Modules enabled later inherit it. New skin profiles start with %s.", "Escolher um visual atualiza o módulo de skin e todos os módulos ativados da Suite. Módulos ativados depois herdam o visual. Novos perfis de skin começam com %s.")
T("Cinematic confirmation can be skipped after you choose to exit. Automatic skipping is a separate option and also skips movies. Both stay inactive during combat, and a vehicle sequence always keeps its exit confirmation. Hide tutorials while this helper is enabled, prefill the DELETE word while keeping the final confirmation manual, hide only the successful screenshot notice, or open your character window at merchants on the tab you used last. At the auction house, Blizzard's filter button is marked while Current Expansion Only is off; tick it there once and Blizzard keeps it for this character.", "A confirmação pode ser ignorada depois que você escolher sair. Pular automaticamente é uma opção separada que também inclui os vídeos. Ambas ficam inativas em combate, e uma sequência em veículo sempre mantém sua confirmação de saída. Este assistente pode ocultar tutoriais, preencher a palavra de exclusão mantendo manual a confirmação final, ocultar apenas o aviso de captura de tela concluída ou abrir sua janela de personagem nos vendedores, na última aba usada. Na casa de leilões, o botão de filtros da Blizzard fica marcado enquanto \"Somente expansão atual\" estiver desligado; marque-o ali uma vez e a Blizzard o mantém para este personagem.")
T("Cinematic zone and event announcements in the Suite look.", "Anúncios cinematográficos de zona e eventos no visual da Suite.")
