T("Clean Modern is the Retail default; MSUF Forever is the Forever default. Midnight Blue keeps the original blue glass. Open a section's three-dot menu to change its colors, or use MSUF Colors for the full palette. Your own color changes become Custom.", "Moderno limpo é o padrão do Retail; MSUF Forever é o padrão do Forever. Midnight Blue mantém o vidro azul original. Abra o menu de três pontos de uma seção para mudar suas cores ou use Cores do MSUF para toda a paleta. Suas alterações de cor passam a ser Personalizado.")
T("Clean Modern uses matte panels with white accents. Midnight Blue keeps the original blue palette. Midnight Dark uses neutral charcoal glass; MSUF Forever retains its muted gold. Color changes become Custom.", "Moderno limpo usa painéis foscos com detalhes brancos. Midnight Blue mantém a paleta azul original. Midnight Dark usa vidro carvão neutro; MSUF Forever mantém o dourado suave. Alterações de cor passam a ser Personalizado.")
T("Clean Modern, Midnight Blue, Midnight Dark and MSUF Forever are complete looks in Style. Color palettes here change colors only; use Expert mode for every UI state.", "Moderno limpo, Midnight Blue, Midnight Dark e MSUF Forever são visuais completos em Estilo. Aqui as paletas de cores só mudam as cores; use o modo Avançado para cada estado da interface.")
