T("Enter a spell name or ID on MSUF action bars. Its buttons glow from this buff on you. A page change in combat pauses the glow until combat ends.", "Digite o nome ou ID de um feitiço nas barras do MSUF. Os botões brilham conforme este benefício em você. Uma mudança de página em combate pausa o brilho até sair de combate.")
T("Enter a talent or spell name or ID, then press Enter. Every required spell must be learned. Empty removes this condition.", "Digite o nome ou ID de um talento ou feitiço e pressione Enter. Todos os feitiços exigidos devem ser conhecidos. Deixe vazio para remover esta condição.")
T("Enter a talent or spell name or ID, then press Enter. The entry is hidden while any excluded spell is learned. Conditions update outside combat.", "Digite o nome ou ID de um talento ou feitiço e pressione Enter. A entrada fica oculta se qualquer feitiço excluído for conhecido. As condições são atualizadas fora de combate.")
T("Enter a texture file ID.", "Insira um ID de arquivo de textura.")
