T("Equipment category", "Categoria de equipamento")
T("Equipment choices", "Escolha de equipamento")
T("Equipment choices (the list that opens from a gear slot) show the item level on each item, so you can compare without hovering. The arrows beside the gear slots can be hidden; hold Alt over a slot to open its choices.", "A escolha de equipamento (a lista que abre a partir de um espaço) mostra o nível de cada item para comparar sem passar o mouse. As setas ao lado dos espaços podem ser ocultadas; segure Alt sobre um espaço para abrir suas opções.")
T("Equipment item levels appear in the upper right of each slot. Choose a font, outline, shadow and Smooth, Sharp or Slug rendering. Slug has no shadow. Missing item data appears when the client provides it.", "Os níveis de item do equipamento aparecem no canto superior direito de cada espaço. Escolha fonte, contorno, sombra e renderização Suave, Nítida ou Slug. Slug não tem sombra. Dados de itens ausentes aparecem quando o cliente os fornece.")
