T("How cooldown icons react. Single spells can differ: click them in the preview.", "Como os ícones de recarga reagem. Feitiços individuais podem ser diferentes: clique neles na prévia.")
T("How the icons line up and grow. A free bar's position counts from the screen center; an attached bar's is an offset from its attach point. Excess cooldowns can move past Maximum icons to another enabled cooldown bar. The destination must have overflow off; chained routes are ignored.", "Alinhamento e crescimento dos ícones. A posição de uma barra livre parte do centro da tela; a de uma barra ancorada é relativa ao ponto de ancoragem. Recargas além do máximo de ícones podem passar a outra barra ativa. O destino deve ter o transbordamento desativado; encaminhamentos em cadeia são ignorados.")
