T("Inside a raid the tracker turns into an encounter view at its usual place: boss name, pull timer, the bosses engaged right now with their health, your best wipe and your fastest kill. Phases come from DBM or BigWigs when one is installed; otherwise the phase stays open. A wipe with more bosses down beats one with fewer, and with the same count the one with less boss health left wins. Each character keeps its own records. Boss health shows only while the client reveals it.", "Dentro de uma raide, o rastreador vira uma visão do encontro no lugar de sempre: nome do chefe, cronômetro do pull, os chefes em combate com a vida, seu melhor wipe e seu abate mais rápido. As fases vêm do DBM ou do BigWigs quando um deles está instalado; caso contrário, a fase fica em aberto. Um wipe com mais chefes derrotados supera um com menos e, com o mesmo número, vence o que deixa menos vida aos chefes. Cada personagem guarda os próprios registros. A vida dos chefes só aparece enquanto o cliente a revela.")
