T("Keep Blizzard grid, or choose one Suite grid, physical bag groups or categories. Use Edit categories in the bag window to create, rename, reorder or disable your categories; drop items onto a sidebar category to assign them. Scroll or use Previous and Next for larger inventories; in combat every slot is shown at once. Combined stack counts are visual only; physical stacks are always restored at the bank, guild bank, mail, trade, auction house and merchant.", "Mantenha a grade da Blizzard ou escolha uma grade da Suite, grupos por bolsa física ou categorias. Use Editar categorias na janela das bolsas para criar, renomear, reordenar ou desativar categorias; solte itens em uma categoria lateral para atribuí-los. Role ou use Anterior e Próximo para inventários maiores; em combate, todos os espaços aparecem de uma vez. A soma das pilhas é apenas visual; as pilhas físicas sempre são restauradas no banco, banco da guilda, correio, trocas, leilão e mercadores.")
