T("MSUF icons replace the scattered Blizzard chat controls. Friends, channels, text to speech and the chat menu keep their Blizzard actions; the bottom icon jumps to the newest message. Turn this off to restore the native buttons.", "Ícones do MSUF substituem os controles de bate-papo espalhados da Blizzard. Amigos, canais, conversão de texto em voz e o menu do bate-papo mantêm suas ações da Blizzard; o ícone inferior salta para a mensagem mais recente. Desative isto para restaurar os botões nativos.")
