T("Observed enemies adds up the enemy forces of the living enemies in combat that you see as a nameplate or target, and the total they would bring. Enemies that give no forces count as zero; while the client keeps a value hidden, the line shows -- instead of a guess. Enemies out of sight are not counted.", "Inimigos observados soma as forças inimigas dos inimigos vivos em combate que você vê como placa de nome ou alvo, e o total que eles renderiam. Inimigos que não dão forças contam como zero; enquanto o cliente esconde um valor, a linha mostra -- em vez de um palpite. Inimigos fora de vista não são contados.")
