T("Priority: focus, safe tank aggro, threat, tapped, quest, neutral, then NPC type. Turning focus off allows the next rule. Disabled threat overrides preserve Blizzard's active threat color. Tank mode uses your effective role; warnings also work for damage/healers. Secret values stay with Blizzard.", "Prioridade: foco, aggro seguro de tanque, ameaça, reivindicado, missão, neutro e, por fim, tipo de PNJ. Desativar o foco libera a próxima regra. Substituições de ameaça desativadas preservam a cor de ameaça ativa da Blizzard. O modo tanque usa sua função efetiva; os avisos também funcionam para dano/curadores. Valores secretos ficam com a Blizzard.")
