T("Reminders appear only outside combat. The advance setting also shows active buffs, food and weapon enchants when their remaining time reaches the chosen number of minutes; 0 shows only missing effects. A single scheduled wakeup handles the next threshold. Reminders hide in arenas and battlegrounds, where aura data can be restricted.", "Os lembretes aparecem apenas fora de combate. A opção de antecedência também mostra bônus ativos, comida e encantamentos de arma quando o tempo restante chega ao número de minutos escolhido; 0 mostra apenas efeitos ausentes. Um único despertar agendado cuida do próximo limite. Os lembretes ficam ocultos em arenas e campos de batalha, onde os dados de aura podem ser restritos.")
T("Reminders for missing poisons and consumables.", "Lembretes de venenos e consumíveis ausentes.")
