T("Replace objectives with the Mythic+ timer during a key", "Substituir objetivos pelo cronômetro de Mítica+ durante uma chave")
T("Replaces the merchant's pages with one list; scroll it with the mouse wheel or the bar. Right-click buys, left-click picks an item up and Shift-click asks for a quantity; linking and previewing work as usual. Purchases paid with currencies or items, or costing at least 150 gold, ask for confirmation first. The buyback tab keeps Blizzard's layout. Drop or click an item from your bags onto the list to sell it; one you can still refund asks whether to refund it.", "Substitui as páginas do mercador por uma única lista; role com a roda do mouse ou a barra. Clique direito compra, clique esquerdo pega um item e Shift-clique pede uma quantidade; vincular e visualizar funcionam como sempre. Compras pagas com moedas ou itens, ou que custam pelo menos 150 de ouro, pedem confirmação antes. A aba de recompra mantém o layout da Blizzard. Solte ou clique com um item das bolsas na lista para vendê-lo; um que ainda pode ser reembolsado pergunta se deve reembolsá-lo.")
T("Report junk sale requests in chat", "Informar pedidos de venda de sucata no bate-papo")
T("Reports group member deaths in chat during combat.", "Relata mortes de membros do grupo no chat durante o combate.")
T("Reports the first observed death of each group member during combat. Local chat, a screen notice and a sound can be selected separately. Simultaneous deaths share one sound. Optionally include your own death. The listener is active only while you are grouped and in combat.", "Avisa a primeira morte observada de cada membro do grupo durante o combate. Chat local, aviso na tela e som podem ser escolhidos separadamente. Mortes simultâneas compartilham um único som. Você pode incluir sua própria morte. A detecção só fica ativa enquanto você está em grupo e em combate.")
