T("Restores this bar's default spells and buffs for your specialization. Other bars and specializations stay as they are. You can undo it.", "Restaura os feitiços e bônus padrão desta barra para sua especialização. Outras barras e especializações permanecem como estão. Você pode desfazer isso.")
T("Results and details", "Resultados e detalhes")
T("Resurrection offers", "Ofertas de ressurreição")
T("Retail Druids only. Every incoming whisper in combat is a possible Innervate cue; message text cannot be inspected reliably during chat lockdown. The alert waits for a publicly known Innervate cooldown, or shows a generic cue when readiness is unavailable. A preferred target can be outlined on an MSUF group frame resolved outside combat. MSUF Edit Mode previews the alert and edits its position and size.", "Apenas Druidas no Retail. Todo sussurro recebido em combate é um possível aviso de Estimular; o texto da mensagem não pode ser inspecionado de forma confiável durante o bloqueio do bate-papo. O alerta espera por uma recarga de Estimular publicamente conhecida ou mostra um aviso genérico quando a disponibilidade não pode ser lida. Um alvo preferido pode ser contornado em um quadro de grupo do MSUF identificado fora de combate. O Modo de Edição do MSUF mostra uma prévia do alerta e edita sua posição e tamanho.")
T("Retail only. Shows while Skyriding is available, or only in flight if selected. Choose bars or Blizzard Vigor gems; gem scale and a refill sound are optional. Separate bar heights, Surge icon size and speed-value offsets are under Text and bars. MSUF Edit Mode previews the HUD. Unknown charge values display as dashes.", "Apenas Retail. Mostra quando voo dinâmico está disponível ou, por opção, só em voo. Escolha barras ou gemas de vigor Blizzard; escala e som de recarga são opcionais. Alturas separadas, tamanho do ícone de surto e deslocamentos de velocidade ficam em Texto e barras. O modo de edição MSUF mostra uma prévia. Cargas desconhecidas aparecem como traços.")
T("Return to the current fight when combat starts", "Voltar à luta atual quando o combate começar")
T("Returns this specialization to its short raid essentials list. Your other bars and specializations stay as they are. You can undo it.", "Devolve esta especialização à lista curta de essenciais de raide. Suas outras barras e especializações permanecem como estão. Você pode desfazer isso.")
