T("Start with a look, then tune its artwork, glow and plate. Changing a detail switches the preset label to Custom without losing the other settings.", "Comece com um visual e depois ajuste a arte, o brilho e a placa. Alterar um detalhe muda o rótulo da predefinição para Personalizado sem perder as outras configurações.")
