T("Switch between native tabs, combined bank, combined warbank and shared categories with the button below the bank window. Shared categories include accessible character and warbank tabs. Manage bank tabs returns to Blizzard purchases, deposits and tab settings. Every slot keeps its own item action and bank stacks are never merged; clicking a warband item selects Blizzard's Warband Bank tab first, and a refundable item asks before it enters the warband bank.", "Alterne entre abas nativas, banco combinado, banco de bando de guerra combinado e categorias compartilhadas com o botão abaixo da janela do banco. As categorias incluem abas acessíveis do personagem e do bando de guerra. Gerenciar abas do banco retorna às compras, depósitos e configurações da Blizzard. Cada espaço mantém sua própria ação e pilhas do banco nunca são combinadas; clicar em um item do bando de guerra seleciona primeiro a aba Banco do Bando de Guerra da Blizzard, e um item reembolsável pergunta antes de entrar no banco do bando de guerra.")
T("Switch each bar on or off here. Turning it back on restores its previous visibility mode. Select Layout to customize the bar selected above.", "Ative ou desative cada barra aqui. Ao ativá-la, o modo de visibilidade anterior é restaurado. Selecione Layout para personalizar a barra escolhida acima.")
T("Switch the whole Skinning module here, or adjust Blizzard and Suite windows separately below.", "Ative ou desative todo o módulo de skin aqui ou ajuste as janelas da Blizzard e da Suite separadamente abaixo.")
