T("Ten action bars plus stance and pet bars with free layout, paging, visibility rules and button styling. Key bindings keep using Blizzard's commands.", "Dez barras de ações, mais as barras de posturas e do ajudante, com layout livre, paginação, regras de visibilidade e estilo de botões. As teclas de atalho continuam usando os comandos da Blizzard.")
