T("The Glass material with MSUF Forever graphite, ivory and muted-gold colors.", "O material Vidro com as cores grafite, marfim e dourado suave do MSUF Forever.")
T("The Great Vault is available only in Retail", "O Grande Cofre só está disponível no Retail")
T("The Mapko skin for Blizzard nameplates. Blizzard keeps health, threat, casts, auras, selection and click handling.", "O visual Mapko para as placas da Blizzard. A Blizzard mantém vida, ameaça, lançamentos, auras, seleção e cliques.")
T("The Suite Cooldown manager page (CDM) shows Blizzard's tracked cooldowns and buffs as bars you arrange and style freely.", "A página Gerenciador de recargas (CDM) do Suite mostra as recargas e os benefícios monitorados pela Blizzard em barras que você pode organizar e personalizar livremente.")
T("The Suite Minimap page styles the minimap itself: size, shape, border, zoom, buttons and info texts. MSUF's own minimap icon is under Miscellaneous.", "A página Minimapa do Suite personaliza o próprio minimapa: tamanho, formato, borda, zoom, botões e textos informativos. O ícone de minimapa do MSUF fica em Diversos.")
T("The Suite Nameplates page styles Blizzard's enemy and friendly nameplates. MSUF's aura filters only decide whether nameplate-only auras show on MSUF frames.", "A página Placas de nome do Suite personaliza as placas de nome de inimigos e aliados da Blizzard. Os filtros de auras do MSUF apenas determinam se auras exclusivas das placas de nome aparecem nos quadros do MSUF.")
T("The Suite draws its own tracker and hides Blizzard's while it runs. Entries are sorted into groups: the focused quest, campaign and important quests, quests ready to hand in, regular quests, world quests, nearby bonus objectives, scenario and delve steps, and tracked achievements. In a raid it can hide completely, only while a boss is engaged, or pause the regular list during any raid fight; the encounter view keeps running then. Quest symbols come as Suite letters or as Blizzard's icons, and the heading line can be switched off. The key binding Use tracked quest item uses the focused quest's item, else the first usable one, and picks a new item only outside combat. Left-click a group name to fold it or a quest to open its log entry; right-click for more actions.", "A Suite desenha o próprio rastreador e oculta o da Blizzard enquanto está ativa. As entradas são organizadas em grupos: a missão em foco, missões de campanha e importantes, missões prontas para entregar, missões comuns, missões mundiais, objetivos bônus próximos, etapas de cenários e imersões, e conquistas rastreadas. Em uma raide, ele pode sumir por completo, só enquanto um chefe está em combate ou pausar a lista comum durante qualquer combate de raide; a visão do encontro continua funcionando. Os símbolos de missão são letras da Suite ou ícones da Blizzard, e a linha de título pode ser desligada. O atalho «Usar item da missão rastreada» usa o item da missão em foco, senão o primeiro utilizável, e só escolhe um novo item fora de combate. Clique com o botão esquerdo no nome de um grupo para recolhê-lo ou em uma missão para abrir sua entrada no registro; o botão direito mostra mais ações.")
T("The Suite frames Blizzard's original Micro Buttons. Their artwork, clicks, tooltips, enabled states and notifications stay native. Queue and FPS indicators stay at Blizzard's Edit Mode position. No recurring MSKIN update runs.", "A Suite emoldura os microbotões originais da Blizzard. A arte, os cliques, as dicas, os estados de ativação e as notificações continuam originais. Os indicadores de fila e FPS ficam na posição do Modo de Edição da Blizzard. Nenhuma atualização recorrente do MSKIN é executada.")
T("The Suite look gives Blizzard's dialogs a dark panel, and the Suite font sets their text font and size; each works alone, and without them dialogs keep Blizzard's look and fonts. A minimum height makes short dialogs taller once Blizzard has sized them; 0 keeps Blizzard's height. A custom position moves the first dialog and the ones Blizzard stacks below it; place it and set the height in MSUF Edit Mode.", "O visual da Suite dá aos diálogos da Blizzard um painel escuro, e a fonte da Suite define a fonte e o tamanho do texto; cada um funciona sozinho e, sem eles, os diálogos mantêm o visual e as fontes da Blizzard. Uma altura mínima deixa os diálogos curtos mais altos depois que a Blizzard os dimensiona; 0 mantém a altura da Blizzard. Uma posição personalizada move o primeiro diálogo e os que a Blizzard empilha abaixo; posicione-o e defina a altura no modo de edição do MSUF.")
T("The Suite skin engine is unavailable.", "O mecanismo de skin da Suite está indisponível.")
T("The chosen profile supplies all settings. Toggle which Suite modules are enabled in it.", "O perfil escolhido fornece todas as configurações. Escolha quais módulos da Suite ficam ativados nele.")
T("The class buff is included only when your character knows it. Enter self-buff spell IDs separated by spaces or commas. For a consumable, enter item ID:aura ID; separate pairs with commas. Up to 12 total reminders are shown. Weapon enchant items use the main-hand or off-hand enchant state.", "O bônus de classe só é incluído quando seu personagem o conhece. Insira IDs de feitiço de bônus próprios separados por espaços ou vírgulas. Para um consumível, insira ID do item:ID da aura; separe os pares com vírgulas. São mostrados até 12 lembretes no total. Itens de encantamento de arma usam o estado de encantamento da mão principal ou secundária.")
T("The combined bag and reagent bag use a Suite panel with a distinct header, border, and accent line. Set background opacity to 0 for a transparent window; item slots stay visible.", "A bolsa combinada e a bolsa de reagentes usam um painel da Suite com cabeçalho, borda e linha de destaque próprios. Defina a opacidade do fundo como 0 para uma janela transparente; os espaços de itens continuam visíveis.")
T("The combined bag setting is protected on this client", "A opção de bolsa combinada é protegida neste cliente")
T("The configuration cannot be opened during combat.", "A configuração não pode ser aberta em combate.")
T("The cooldown manager is not loaded.", "O Gerenciador de Recargas não está carregado.")
T("The cooldown manager needs an update. Reload the interface.", "O Gerenciador de Recargas precisa de uma atualização. Recarregue a interface.")
T("The cooldown manager was reset: settings, spell lists and spell options.", "O Gerenciador de Recargas foi redefinido: configurações, listas de feitiços e opções de feitiço.")
T("The countdown turns to the warning color below this many seconds. All bars: the Text section's setting.", "A contagem regressiva muda para a cor de aviso abaixo deste número de segundos. Todas as barras: a configuração da seção Texto.")
T("The dark sweep over the icon while it counts down.", "A varredura escura sobre o ícone durante a contagem regressiva.")
T("The default font follows MSUF Fonts while the default size follows Blizzard's chat size. Choose Blizzard chat font to keep its own face. Slug has no shadow.", "A fonte padrão segue as Fontes do MSUF, enquanto o tamanho padrão segue o tamanho do bate-papo da Blizzard. Escolha Fonte do bate-papo da Blizzard para manter a fonte original dele. Slug não tem sombra.")
T("The dungeon's timer", "O cronômetro da masmorra")
T("The engine remains dormant until a lifecycle event or an explicit user action requires work.", "O motor permanece inativo até que um evento do ciclo de vida ou uma ação explícita do usuário exija trabalho.")
T("The global cooldown can leave the ring for a fixed circle of its own size and opacity, shown next to casts. Place it in MSUF Edit Mode; its button there works while this choice is on.", "A recarga global pode sair do anel para um círculo fixo com tamanho e opacidade próprios, mostrado junto dos lançamentos. Posicione-o no modo de edição do MSUF; o botão dele lá funciona enquanto esta opção estiver ligada.")
T("The header shows the meter and fight. Its buttons change the meter and fight directly in the window.", "O cabeçalho mostra o medidor e a luta. Os botões dele mudam o medidor e a luta diretamente na janela.")
T("The keystone notice remains local. The optional group announcement forwards only Blizzard's confirmed reset message immediately after your own reset request, while you are group leader. Failed attempts and resets by other players are not announced.", "O aviso de pedra-chave continua local. O anúncio opcional ao grupo encaminha apenas a mensagem de redefinição confirmada da Blizzard logo após seu próprio pedido, enquanto você é líder do grupo. Tentativas falhas e redefinições de outros jogadores não são anunciadas.")
T("The macro builder is available only in Retail", "O construtor de macro está disponível apenas em Retail")
T("The macro exceeds the 255-character limit", "A macro excede o limite de 255 caracteres")
T("The map grows or shrinks to the chosen width and height while the pointer is over it, then returns to its normal size. A circular map keeps its height equal to its width.", "O mapa aumenta ou diminui para a largura e a altura escolhidas enquanto o ponteiro está sobre ele e depois volta ao tamanho normal. Um mapa circular mantém a altura igual à largura.")
T("The merchant's offers changed; nothing was bought.", "As ofertas do mercador mudaram; nada foi comprado.")
T("The merchant's whole stock in one scrolling list with prices, quality colors and item levels.", "Todo o estoque do mercador em uma lista rolável com preços, cores de qualidade e níveis de item.")
T("The minutes below", "Os minutos abaixo")
T("The mouse wheel zooms the map. Middle-click runs the chosen action; left and right clicks keep working as usual.", "A roda do mouse dá zoom no mapa. O clique do meio executa a ação escolhida; os cliques esquerdo e direito funcionam normalmente.")
T("The native input box keeps autocomplete, links and chat commands.", "A caixa de entrada nativa mantém o autocompletar, os links e os comandos de bate-papo.")
T("The normal warning time", "O tempo de aviso normal")
T("The optional glyph layer changes appearance while Blizzard keeps clicks, tooltips, enabled states and notifications. Queue and FPS indicators stay at Blizzard's Edit Mode position. No recurring MSKIN update runs.", "A camada opcional de glifos muda a aparência enquanto a Blizzard mantém cliques, dicas, estados de ativação e notificações. Os indicadores de fila e FPS ficam na posição do Modo de Edição da Blizzard. Nenhuma atualização recorrente do MSKIN é executada.")
T("The options module could not be loaded: %s", "Não foi possível carregar o módulo de opções: %s")
T("The options module did not finish initializing.", "O módulo de opções não terminou de inicializar.")
T("The party table grows in steps: characters with build and score, then the combat figures of Blizzard's damage meter, then the loot seen in chat. Each character keeps its latest runs; open the newest here or with /msufruns and step through older ones. Deleting a run asks for a second click. The card can wait until you close the chest's loot window.", "A tabela do grupo cresce em etapas: personagens com configuração e pontuação, depois os números de combate do medidor de dano da Blizzard, depois o saque visto no chat. Cada personagem guarda suas corridas mais recentes; abra a mais nova aqui ou com /msufruns e avance para as mais antigas. Excluir uma corrida pede um segundo clique. O cartão pode esperar até você fechar a janela de saque do baú.")
T("The preview and every section below edit this bar. Shared custom groups start with a separate list for explicit spell, aura and item IDs; disabling sharing restores the existing per-specialization list.", "A prévia e todas as seções abaixo editam esta barra. Grupos personalizados compartilhados começam com uma lista separada de IDs explícitos de feitiços, auras e itens; desativar o compartilhamento restaura a lista existente por especialização.")
T("The preview needs the cooldown manager.", "A prévia precisa do Gerenciador de Recargas.")
T("The quick switch above remembers this mode when you turn the bar off. Choose Never to keep it hidden.", "O botão rápido acima lembra este modo quando você desativa a barra. Escolha Nunca para mantê-la oculta.")
T("The settings you change most. Attach the bar to another bar or to your player frame to keep them together; the gap is the space between them. Center keeps the first cooldown icon in the middle and adds the next icons right, left, right, left. Visible buffs stay compact; on a horizontal mixed bar, player and target buffs grow outward from the center on one row.", "As configurações que você mais altera. Anexe a barra a outra barra ou ao seu quadro de jogador para mantê-las juntas; o espaço é a distância entre elas. Centro mantém o primeiro ícone de recarga no meio e adiciona os próximos à direita, à esquerda, à direita, à esquerda. Bônus visíveis ficam compactos; em uma barra mista horizontal, os bônus do jogador e do alvo crescem para fora a partir do centro em uma única linha.")
T("The socket window is available only in Retail", "A janela de engaste está disponível apenas em Retail")
T("The stack condition uses Glow at stacks and Stack comparison. Buff absence cannot drive a combat glow through the native aura-slot API.", "A condição usa o limite de brilho e a comparação de aplicações. A ausência de um benefício não pode ativar brilho em combate pela API nativa de espaços de aura.")
T("Theme", "Tema")
T("Theme-colored icon outline", "Contorno do ícone na cor do tema")
T("These apply to every bar. The standalone assisted icon follows Blizzard's assisted combat highlight; enable that highlight in the game's Combat options. Its position is available in MSUF Edit Mode. Action bar presses show on cooldown icons only with the MSUF Suite action bars.", "Estas opções se aplicam a todas as barras. O ícone independente segue o destaque de assistência de combate da Blizzard; ative-o nas opções de Combate do jogo. A posição pode ser ajustada no Modo de Edição do MSUF. Os pressionamentos da barra de ações aparecem nos ícones de recarga apenas com as barras de ações do MSUF Suite.")
T("These apply to every bar:", "Estas valem para todas as barras:")
T("These choices apply to this spell on every bar and specialization.", "Estas escolhas valem para este feitiço em todas as barras e especializações.")
T("These settings apply to all bars until a bar uses its own style.", "Estas configurações valem para todas as barras até que uma barra use seu próprio estilo.")
T("Thick outline", "Contorno grosso")
T("Thick outline + SLUG", "Contorno grosso + SLUG")
T("Thick outline + shadow", "Contorno grosso + sombra")
T("Thin", "Fino")
