T("This bar sits on Blizzard's Essential bar, which your MSUF frames follow. Move it in Blizzard's Edit Mode.", "Esta barra fica sobre a barra Essenciais da Blizzard, que seus quadros do MSUF seguem. Mova-a no Modo de Edição da Blizzard.")
T("This bar takes the place of %s, which is off. Move that bar, or attach this one elsewhere.", "Esta barra ocupa o lugar de %s, que está desativada. Mova essa barra ou anexe esta em outro lugar.")
T("This bar's own options are not used by the %s type; the settings below apply to every bar.", "As opções próprias desta barra não são usadas pelo tipo %s; as configurações abaixo valem para todas as barras.")
T("This category already holds 500 items. Remove one before adding another.", "Esta categoria já contém 500 itens. Remova um antes de adicionar outro.")
T("This client has no combined bag setting", "Este cliente não tem a opção de bolsa combinada")
