T("Thrill speed color", "Cor da velocidade de Emoção")
T("Tick every demon you want out; demons your character has not learned yet can be ticked too. A summoned demon you left unticked gets a notice, as long as one of your ticked demons can be summoned. Another look of a demon counts as that demon once you have summoned it in that look.", "Marque cada demônio que você quer ter por perto; também é possível marcar demônios que seu personagem ainda não aprendeu. Um demônio invocado sem marca recebe um aviso, desde que um dos demônios marcados possa ser invocado. Outra aparência de um demônio conta como esse demônio assim que você o tiver invocado com essa aparência.")
T("Tier %d", "Nível %d")
T("Time", "Hora")
