T("Timestamps use Blizzard's chat setting across all chat windows. Copy is off by default; when enabled, move its button with X/Y, choose a message, then press Ctrl+C. The displayed timestamp is included when timestamps are on. The message tools leave the Combat Log alone (its own settings can add a timestamp to every line); its lines still wake the idle fade. Saved history belongs to this character.", "Os carimbos de hora usam a configuração de bate-papo da Blizzard em todas as janelas de bate-papo. Copiar vem desativado por padrão; quando ativado, mova o botão com X/Y, escolha uma mensagem e pressione Ctrl+C. O carimbo de hora exibido é incluído quando os carimbos estão ativados. As ferramentas de mensagens não mexem no registro de combate (as configurações dele podem pôr o horário em cada linha); as linhas dele ainda despertam o esmaecimento por inatividade. O histórico salvo pertence a este personagem.")
