T("Turn off Show combat time to hide both the duration in every meter header and the separate floating timer. The two switches below let you show either one independently.", "Desative Mostrar tempo de combate para ocultar tanto a duração no cabeçalho de cada medidor quanto o cronômetro flutuante separado. As duas opções abaixo permitem mostrar cada um de forma independente.")
