T("Warn when your pet is missing or dead. By default, the missing warning applies to Hunters and Warlocks; the dead warning applies to any class with a pet. MSUF Edit Mode moves the alert.", "Avise quando seu mascote estiver ausente ou morto. Por padrão, o alerta de ausência vale para Caçadores e Bruxos; o alerta de morte vale para qualquer classe com mascote. Mova o alerta no Modo de Edição do MSUF.")
