T("Welcome to MSUF Suite", "Boas-vindas à MSUF Suite")
T("What to remind", "O que lembrar")
T("What to track", "O que rastrear")
T("When a dungeon queue pops", "Quando uma fila de masmorra aparece")
T("When a ready check starts outside combat and your mana as a healer is low, a short note shows how much you have; it turns red below half of your limit. Only your own mana is read.", "Quando uma verificação de prontidão começa fora de combate e sua mana de curador está baixa, uma nota curta mostra quanto você tem; ela fica vermelha abaixo da metade do seu limite. Só a sua própria mana é lida.")
T("When leaving", "Ao sair")
T("When someone offers you a resurrection, its dialog gets a green frame, optionally with Blizzard's ready check sound, and its accept button can get a green frame of its own. Accepting stays your click.", "Quando alguém oferece uma ressurreição, o diálogo ganha uma moldura verde, opcionalmente com o som de verificação de prontidão da Blizzard, e o botão de aceitar pode ganhar sua própria moldura verde. Aceitar continua sendo o seu clique.")
T("When the key ends", "Quando a chave termina")
T("When the native group listing panel closes with applications still active, show their count in your own chat. Your applications remain active and no group chat is sent.", "Quando o painel da busca de grupos fechar com candidaturas ainda ativas, mostre a quantidade no seu próprio chat. Suas candidaturas continuam ativas e nenhuma mensagem é enviada ao grupo.")
T("When the selected bar appears", "Quando a barra selecionada aparece")
T("When this bar shows, and how far it fades out of combat. Tooltips show a spell when you hover its icon. This page and MSUF Edit Mode always show every bar.", "Quando esta barra aparece e quanto ela esmaece fora de combate. As dicas mostram um feitiço quando você passa o mouse sobre o ícone dele. Esta página e o Modo de Edição do MSUF sempre mostram todas as barras.")
T("When to remind", "Quando lembrar")
T("When to show", "Quando mostrar")
T("Where", "Onde")
T("Where are the Suite minimap settings?", "Onde ficam as configurações do minimapa do Suite?")
T("Where are the nameplate settings?", "Onde ficam as configurações das placas de nome?")
T("Where is the cooldown manager?", "Onde fica o gerenciador de recargas?")
T("Where the buff or debuff is looked for. Automatic: harmful spells on your target, all others on you.", "Onde o bônus ou a penalidade é procurado. Automático: feitiços nocivos no seu alvo, todos os outros em você.")
T("Where to show recent actions", "Onde mostrar ações recentes")
T("Which number is drawn on top when both show.", "Qual número é desenhado por cima quando ambos aparecem.")
T("Which numbers show, which one is drawn on top, and their size and place. Single spells can differ: click them in the preview. The font settings below apply to every bar; Slug has no shadow.", "Quais números aparecem, qual é desenhado por cima, além do tamanho e da posição deles. Feitiços individuais podem ser diferentes: clique neles na prévia. As configurações de fonte abaixo valem para todas as barras; Slug não tem sombra.")
T("While DataTexts and this choice are enabled, MSUF remembers this character's gold at login and after money changes. Hover a Gold or Session gold DataText to see the last known account total and up to eight other characters. No background scans are used.", "Enquanto os textos de dados e esta opção estiverem ativos, o MSUF registra o ouro do personagem ao entrar e após alterações de dinheiro. Passe o mouse sobre um texto Ouro ou Ouro da sessão para ver o último total conhecido da conta e até oito outros personagens. Nenhuma varredura em segundo plano é usada.")
T("While DataTexts is active, hide Blizzard's backpack and bag slots. A Bag space DataText opens the native bags when clicked. Turn this off to restore the Blizzard buttons.", "Enquanto os Textos informativos estiverem ativos, oculta a mochila e os espaços de bolsa da Blizzard. Um texto informativo Espaço nas bolsas abre as bolsas nativas ao ser clicado. Desative isto para restaurar os botões da Blizzard.")
T("While a key runs, each defeated boss shows how far ahead or behind you are: against the best time you ever had on that boss, or against the boss times of your fastest completed run, at this keystone level or at any. Only runs this character completed count. With target times on, bosses still alive show the time to beat.", "Durante uma chave, cada chefe derrotado mostra o quanto você está à frente ou atrás: em relação ao seu melhor tempo naquele chefe ou aos tempos dos chefes da sua corrida concluída mais rápida, neste nível de chave ou em qualquer um. Só contam as corridas concluídas por este personagem. Com os tempos-alvo ativados, os chefes ainda vivos mostram o tempo a superar.")
T("While the buff of this spell lasts, the icon shows its duration and stacks instead of the cooldown.", "Enquanto o bônus deste feitiço durar, o ícone mostra a duração e os acúmulos dele em vez da recarga.")
